  ["c226ba2e18e10308"] = { "Non posso, in buona coscienza, perdere tempo ad addestrare novellini mentre i nostri alleati, i non morti, soffrono così terribilmente. Ti prego, parla invece con Kray, laggiù: per ora può aiutarti lui.", "." },
  ["c236e1cc4c024234"] = { "Scommetto che adesso te ne penti, eh, {name}!?!", "." },
