  ["c2462b58979d0e13"] = { "Via, creature immonde! Tornate nel vuoto da cui il vostro padrone vi ha plasmato!", "." },
  ["c24dc1d7123f9293"] = { "|cffffff00La Torre di Levante è stata conquistata dall'⟦Alliance=Alleanza⟧!|r", "." },
  ["c2516517c1d9e9e0"] = { "In queste terre nessuno segue le tracce meglio di Drayl. Lo trovi sull'⟦Hunter Rise=Altura dei Cacciatori⟧.", "." },
  ["c25a323f0bd0e430"] = { "Cosa sono i Darkmoon Faire Prize Ticket e come li ottengo?", "." },
  ["c25ba09558fdd520"] = { "Dovrei parlare con Dewey di qualche sistema di annotazione per tenere più in ordine questi registri.", "." },
  ["c260a1d169552831"] = { "Il Dun Baldar South Bunker è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo distruggerà!", "." },
  ["c26352944593f16a"] = { "La corruzione vile non ha risparmiato nessuna delle creature del ⟦Felwood=Vilbosco⟧, {name}. Ti prego, stai in guardia.", "." },
  ["c26597daac067a68"] = { "Puoi dirmi dove si trova Brine?", "." },
  ["c26a268f6b8f7db2"] = { "%s chiama in suo aiuto un ⟦Blackhand Veteran=Veterano Manonera⟧!", "." },
  ["c26ec7289666ab64"] = { "Non finiranno mai questi incessanti attacchi del Flagello?", "." },
  ["c2767ae4ff60101b"] = { "Ora muori!", "." },
  ["c27b2e77622165b6"] = { "Sprecherei il tuo oro e il mio tempo se ti insegnassi a pilotare un tecnostruzzo, {class}. Sei semplicemente troppo <grosso/grossa>!", "." },
  ["c2805d817b5a606f"] = { "Il dolore è insopportabile!", "." },
  ["c2848c45a860570d"] = { "Tre settimane dopo ho riaperto gli occhi in un letto della ⟦Northshire=Contea del Nord⟧. Non ricordo un accidente.", "." },
  ["c28cb3ea2b7348f2"] = { "Neanche un saluto per il tuo vecchio amico Narain? Chi ti aspettavi???", "." },
  ["c292bf0ec4805527"] = { "I trogg stanno riconquistando la ⟦Irondeep Mine=Miniera di Ferrofondo⟧!", "." },
  ["c2956c30fa59f891"] = { "Il ⟦First Aid=Primo Soccorso⟧ è sempre un'abilità utile. In battaglia mi ha salvato la pelle più di una volta. Passa da Spiritual Healing, sull'⟦Spirit Rise=Altura degli Spiriti⟧. ⟦Pand Stonebinder=Pand Lega Pietre⟧ può insegnarti tutto ciò che serve per salvare anche la tua pelle.", "." },
  ["c2995de73a5cd75d"] = { "Hai già trovato Arra'chea?", "." },
  ["c29e87d4397a3047"] = { "Sì. {name}. Ho localizzato il Signore della Foresta. Dobbiamo raddoppiare gli sforzi! Servono altri cristalli!", "." },
  ["c2a59804d5332de0"] = { "La tua prigionia è finita, ⟦Doom'rel=Teneb'rel⟧. Ti sfido!", "." },
  ["c2a5bff23f6a6c2a"] = { "<Quel/Quella> {name} vuole la mia morte! Aiuto!", "." },
  ["c2a932e419adfac9"] = { "Hai già imparato tutto ciò che posso insegnarti, {name}. Parla con l'elfa della notte ⟦Lilyssia Nightbreeze=Lilyssia Frescanotte⟧ nel ⟦Mage Quarter=Quartiere dei Maghi⟧ di ⟦Stormwind=Roccavento⟧, se vuoi continuare i tuoi studi. Ho sentito dire che è una brava insegnante.", "." },
  ["c2ac40c9f7f7f257"] = { "Throm'ka, {class}. Tutto il materiale bellico è nella fase finale di preparazione e viene inviato a ⟦Silithus=Silitus⟧. Dovrebbe arrivare nel corso dei prossimi $2113w giorni. Con l'equipaggiamento pronto e le nostre forze schierate, non resterà che aspettare qualcuno che suoni il gong sull'Altare dello Scarabeo, che dovrebbe aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ e dare inizio alla guerra.\n\nLok'tar Ogar!", "." },
  ["c2b02eb5f68a2a9b"] = { "Chi ti ha mandato qui? Non sei ancora <pronto/pronta> per il mio insegnamento! Ti verrà detto quando sarai <pronto/pronta>.", "." },
  ["c2b11ab89e569b14"] = { "Preparati, {name}. Vado ad aprire la fenditura...", "." },
  ["c2b2b65fe03b6a67"] = { "Setaccerò la terra in cerca di questo Earthshaper. E l'essenza?", "." },
  ["c2b83e86400d097a"] = { "%s ascolta {name} che gli racconta le sue avventure nelle ⟦Badlands=Maleterre⟧.", "." },
  ["c2c28cc3f5e65b30"] = { "⟦Grimclaw=Truceartiglio⟧?! Calma, amico mio... dov'è il tuo padrone Volcor?", "." },
  ["c2c66f9fc6665c7e"] = { "Tre urrà per {name}, <ammiraglio/ammiraglia> della flotta dei Bucanieri Velerosse!", "." },
  ["c2c99fc3326f57d9"] = { "Forgiatura", "." },
  ["c2cc5d18e66d46e9"] = { "Noi dovere controllare se nostro Affondo... Affondo... ⟦Brain Hacker=Affondo Cerebrale⟧ venduto ad asta. Tu trovare cassetta della posta vicino a locanda su anello superiore di ⟦Trade Quarter=Quartiere del Commercio⟧.", "." },
  ["c2ccef7538417a71"] = { "Salute. Se cerchi articoli in cuoio, troverai la mia merce ben lavorata.", "." },
  ["c2cf4204c679f26c"] = { "Comincia a parlare chiaro, nano. Non voglio avere niente a che fare con il tuo biscotto, il tuo paparino o qualsiasi tipo di «screditamento».", "." },
  ["c2d1009077d74dbb"] = { "Fermati! <Sciocco/Sciocca> {class}, non possiamo lasciarti evocare la creatura Myzrael!", "." },
  ["c2d45ffd7d127971"] = { "Il ⟦Shadowfang Keep=Forte di Zannascura⟧ si trova nella Selva ⟦Silverpine=Pinargento⟧ meridionale, poco a nord di ⟦Pyrewood Village=Rovonero⟧.", "." },
  ["c2d65e428694ef08"] = { "Ben fatto. Ora hai ottenuto il più alto onore della sartoria. Va' e fa' cose terribili con questo sapere!", "." },
  ["c2dd1c14cfd8e5ef"] = { "Non ti deluderò!", "." },
  ["c2dfd342bb26da08"] = { "Non hai niente a che fare con me, <piccoletto/piccoletta>.", "." },
  ["c2e3cceb41982eaf"] = { "Segnalata attività dei Defias all'orizzonte, lungo la costa. Tutto tranquillo a ⟦Sentinel Hill=Guardiacolle⟧.", "." },
  ["c2e47d34255e93b3"] = { "Ne ho abbastanza dei tuoi piagnistei! Chiudi quel becco prima che te lo chiuda io!", "." },
  ["c2ea85ce43c13b99"] = { "Buona fortuna là fuori, {name}.", "." },
  ["c2eb6ae1fca97b8a"] = { "Ora che il generale dei Lupi Bianchi è stato sconfitto, possiamo distogliere qualche soldato per sorvegliare l'ingresso del ⟦Winterax Hold=Covo degli Asciafredda⟧.\n\nMa resta vigile! Dobbiamo sempre stare all'erta contro gli intrusi dell'⟦Horde=Orda⟧...", "." },
  ["c2f6977ba464602c"] = { "L'attività del Flagello nelle ⟦Plaguelands=Terre Infette⟧ è aumentata di dieci volte. Ci arrivano notizie di attacchi del Flagello fin da Kalimdor! Ora, come pensi che sia successo? Come hanno fatto quei miserabili non morti a compiere ciò che prima si riteneva impossibile? Non c'è più nessun luogo sicuro?", "." },
  ["c2fa187f1eb7c6c8"] = { "Il direttore Riddlevox mi ha messo a capo del programma di sviluppo dei trinciatori dell'Unione. Pochi mesi di lavoro e sono già nei guai! Mi farebbe comodo il tuo aiuto, {name}!", "." },
